import{_ as e,o as d,c as o,a4 as a}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"Wireframe Format","description":"","frontmatter":{"title":"Wireframe Format"},"headers":[],"relativePath":"excel/wireframe-format.md","filePath":"excel/wireframe-format.md","lastUpdated":null}'),r={name:"excel/wireframe-format.md"};function s(n,t,i,l,c,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="wireframe-format" tabindex="-1">Wireframe format <a class="header-anchor" href="#wireframe-format" aria-label="Permalink to &quot;Wireframe format&quot;">​</a></h1><p>The wireframe is the <strong>source of truth</strong> for all campaign content. This page defines the format the CLI expects when preparing or editing the Excel file.</p><h2 id="supported-excel-formats" tabindex="-1">Supported Excel formats <a class="header-anchor" href="#supported-excel-formats" aria-label="Permalink to &quot;Supported Excel formats&quot;">​</a></h2><p>The system auto-detects the format based on column headers:</p><table tabindex="0"><thead><tr><th>Format</th><th>When to use</th><th>Detection</th></tr></thead><tbody><tr><td><strong>CONVERTED</strong></td><td>Standard (recommended)</td><td>Has REFRESH_NAME, REFRESH_DATE, ACTION, ASSET_TYPE, SITE_LOCATION</td></tr><tr><td><strong>BANNER</strong></td><td>Legacy LOFT format</td><td>Has WEB_PROD_CODED, DEVICE with date patterns</td></tr><tr><td><strong>FLAT_TIMED</strong></td><td>Timed refreshes</td><td>Has REFRESH_DATE, START_DATETIME, ACTION</td></tr></tbody></table><h2 id="converted-format-recommended" tabindex="-1">CONVERTED format (recommended) <a class="header-anchor" href="#converted-format-recommended" aria-label="Permalink to &quot;CONVERTED format (recommended)&quot;">​</a></h2><h3 id="required-columns" tabindex="-1">Required columns <a class="header-anchor" href="#required-columns" aria-label="Permalink to &quot;Required columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>REFRESH NAME</code></td><td>Name of the refresh</td><td>&quot;1/26 Winter Sale&quot;</td></tr><tr><td><code>DATE</code> or <code>REFRESH DATE</code></td><td>When content goes live</td><td>1/26/2026</td></tr><tr><td><code>ACTION</code></td><td>What to do</td><td>LAUNCH, NO_CHANGE, REMOVE</td></tr><tr><td><code>SITE LOCATION</code></td><td>Where on site</td><td>HOMEPAGE, PPH, POPUP</td></tr><tr><td><code>ASSET TYPE</code></td><td>Content type</td><td>HOMEPAGE, PPH, COUPONS</td></tr></tbody></table><h3 id="optional-columns" tabindex="-1">Optional columns <a class="header-anchor" href="#optional-columns" aria-label="Permalink to &quot;Optional columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Aliases</th><th>Description</th></tr></thead><tbody><tr><td><code>ZONE</code></td><td>PLACEMENT, PLACEMENT ZONE</td><td>Zone within asset type</td></tr><tr><td><code>COPY</code></td><td>MESSAGE, COPY_MESSAGE, DISCLAIMER</td><td>Marketing copy text</td></tr><tr><td><code>DESTINATION ID</code></td><td>—</td><td>Link destination (category ID or URL)</td></tr><tr><td><code>IPID</code></td><td>—</td><td>Analytics tracking ID</td></tr><tr><td><code>ALT TEXT</code></td><td>—</td><td>Image accessibility text</td></tr><tr><td><code>TIME</code></td><td>START_TIME, TIME (ET)</td><td>Refresh time</td></tr><tr><td><code>START_DATETIME</code> / <code>END_DATETIME</code></td><td>—</td><td>Live window (when campaign is live); drives status <strong>Date/time</strong> display in local time</td></tr><tr><td><code>ORDER</code></td><td>ITEM #, ITEM_ORDER</td><td>Item order within zone</td></tr><tr><td><code>NOTES</code></td><td>—</td><td>Internal notes</td></tr></tbody></table><h3 id="column-name-aliases" tabindex="-1">Column name aliases <a class="header-anchor" href="#column-name-aliases" aria-label="Permalink to &quot;Column name aliases&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You can use</th><th>Recognized as</th></tr></thead><tbody><tr><td>REFRESH NAME, PROJECT SUMMARY, INITIATIVE</td><td>REFRESH_NAME</td></tr><tr><td>DATE, REFRESH DATE, REFRESH_DATE</td><td>REFRESH_DATE</td></tr><tr><td>ACTION, LAUNCH/REMOVE</td><td>ACTION</td></tr><tr><td>COPY, MESSAGE, PLACEMENT NOTES/PPH MESSAGE</td><td>COPY_MESSAGE</td></tr><tr><td>ZONE, PLACEMENT, PLACEMENT ZONE</td><td>ZONE</td></tr><tr><td>LINK/TRACKING, LINK, TRACKING</td><td>Link (parsed for destination)</td></tr></tbody></table><h2 id="sheet-structure-parent-child-rows" tabindex="-1">Sheet structure: parent-child rows <a class="header-anchor" href="#sheet-structure-parent-child-rows" aria-label="Permalink to &quot;Sheet structure: parent-child rows&quot;">​</a></h2><ul><li><strong>Parent row:</strong> Has REFRESH NAME and DATE; no ASSET TYPE.</li><li><strong>Child rows:</strong> Have ACTION, ASSET TYPE, ZONE; they inherit date from the parent.</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REFRESH NAME     │ DATE      │ ACTION │ ASSET TYPE │ ZONE</span></span>
<span class="line"><span>1/26 Winter Sale │ 1/26/2026 │        │            │        ← Parent</span></span>
<span class="line"><span>                 │           │ LAUNCH │ HOMEPAGE   │ HP_HERO  ← Child</span></span>
<span class="line"><span>                 │           │ LAUNCH │ HOMEPAGE   │ HP_2T    ← Child</span></span>
<span class="line"><span>                 │           │ NO_CHANGE │ PPH     │ PPH      ← Child</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="action-types" tabindex="-1">Action types <a class="header-anchor" href="#action-types" aria-label="Permalink to &quot;Action types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Meaning</th><th>System behavior</th></tr></thead><tbody><tr><td><strong>LAUNCH</strong></td><td>New content</td><td>Generates new HTML, registers in asset registry</td></tr><tr><td><strong>UPDATE</strong></td><td>Modify existing</td><td>Re-renders HTML, syncs updated content to SFCC</td></tr><tr><td><strong>REMOVE</strong></td><td>Delete content</td><td>Unregisters zone, deletes from SFCC</td></tr><tr><td><strong>NO_CHANGE</strong></td><td>Same as before</td><td>Reuses asset from registry, no new files</td></tr></tbody></table><h2 id="example-one-row-→-one-asset" tabindex="-1">Example: one row → one asset <a class="header-anchor" href="#example-one-row-→-one-asset" aria-label="Permalink to &quot;Example: one row → one asset&quot;">​</a></h2><p>A single child row with <code>ACTION=LAUNCH</code>, <code>ASSET_TYPE=PPH</code>, <code>ZONE=PPH</code>, <code>COPY=50% off winter</code> becomes one content asset in the refresh JSON under <code>assetsByType.PPH</code>. After build, it appears in the PPH template output and in the OCAPI payload for that slot.</p><h2 id="example-rows-→-json-structure" tabindex="-1">Example: rows → JSON structure <a class="header-anchor" href="#example-rows-→-json-structure" aria-label="Permalink to &quot;Example: rows → JSON structure&quot;">​</a></h2><p>Two sample Excel rows (child rows under a parent with REFRESH NAME and DATE) and the shape of the parsed refresh JSON:</p><p><strong>Excel rows (CONVERTED format):</strong></p><table tabindex="0"><thead><tr><th>REFRESH NAME</th><th>DATE</th><th>ACTION</th><th>ASSET TYPE</th><th>ZONE</th><th>COPY</th><th>DESTINATION ID</th></tr></thead><tbody><tr><td>1/26 Winter Sale</td><td>1/26/2026</td><td>LAUNCH</td><td>HOMEPAGE</td><td>HP_HERO</td><td>50% off winter</td><td>/sale/winter</td></tr><tr><td>1/26 Winter Sale</td><td>1/26/2026</td><td>LAUNCH</td><td>PPH</td><td>PPH</td><td>Free shipping</td><td>/shipping</td></tr></tbody></table><p><strong>Resulting structure in <code>refresh.json</code> (simplified):</strong></p><ul><li><code>campaign.refresh.date</code> = <code>&quot;2026-01-26&quot;</code>, <code>campaign.refresh.name</code> = from parent row.</li><li><code>assetsByType.HOMEPAGE.zones</code> = one zone object with <code>zone: &quot;HP_HERO&quot;</code>, <code>items: [{ action: &quot;LAUNCH&quot;, copy: &quot;50% off winter&quot;, destination: &quot;/sale/winter&quot;, ... }]</code>.</li><li><code>assetsByType.PPH.zones</code> = one zone with <code>zone: &quot;PPH&quot;</code>, <code>items: [{ action: &quot;LAUNCH&quot;, copy: &quot;Free shipping&quot;, destination: &quot;/shipping&quot;, ... }]</code>.</li></ul><p>After <strong>make build</strong>, each zone gets rendered HTML and an asset ID (and IPID for LAUNCH). The OCAPI payload then includes these assets and their slot bindings.</p><h2 id="dates-and-times-excel-vs-status-board" tabindex="-1">Dates and times: Excel vs status board <a class="header-anchor" href="#dates-and-times-excel-vs-status-board" aria-label="Permalink to &quot;Dates and times: Excel vs status board&quot;">​</a></h2><p>The status board shows a <strong>Date/time</strong> column and a <strong>Name</strong> column. They come from different Excel columns and can look different if your sheet uses date prefixes in the name or midnight UTC times.</p><table tabindex="0"><thead><tr><th>Source</th><th>Excel column(s)</th><th>What it controls</th></tr></thead><tbody><tr><td><strong>Folder / row date</strong></td><td><code>DATE</code> / <code>REFRESH DATE</code></td><td>The refresh&#39;s logical date: folder path (<code>refreshes/YYYY-MM-DD/r1</code>) and row ordering on the status board.</td></tr><tr><td><strong>Name</strong></td><td><code>REFRESH NAME</code></td><td>The <strong>Name</strong> column on the status board (e.g. <code>&quot;2/20: $39 FP PANTS / STYLE EVENT EP 40&quot;</code>). The prefix <code>2/20:</code> is just text.</td></tr><tr><td><strong>Date/time column</strong></td><td><code>START_DATETIME</code>, <code>END_DATETIME</code> (optional)</td><td>The <strong>live window</strong> (when the campaign is &quot;live&quot; on the site). Converted to local time for display (e.g. <code>2/19 7pm – 2/19 7pm</code>).</td></tr></tbody></table><p>So:</p><ul><li><strong>Name</strong> can include a date like <code>2/20:</code> (the &quot;go live&quot; day in the label). That does <strong>not</strong> set the live window.</li><li><strong>Date/time</strong> on the board = <code>startTime</code>–<code>endTime</code> from the refresh, shown in <strong>local time</strong>. If you leave start/end blank, they are inferred from the refresh name (e.g. <code>@3PM</code>) or from the next refresh&#39;s start; if you use midnight UTC (<code>2026-02-20T00:00:00.000Z</code>), they will show as the <strong>previous calendar day</strong> in US timezones (e.g. 2/19 4pm or 7pm depending on zone).</li></ul><p>To have the status <strong>Date/time</strong> match the date in the <strong>Name</strong> (e.g. &quot;2/20&quot; in both):</p><ul><li>Use <strong>START_DATETIME</strong> / <strong>END_DATETIME</strong> (or the <strong>TIME</strong> column where supported) with the intended go-live time in the correct timezone (e.g. 7pm ET on 2/20), so that the displayed window lines up with the date in the name.</li></ul><p><strong>Multi-day windows:</strong> A refresh can run across several days (e.g. &quot;2/20 60% off&quot; live from 2/20–2/22). Put the actual start and end datetimes in <strong>START_DATETIME</strong> and <strong>END_DATETIME</strong> (full date+time, e.g. from Excel or ISO). The parser uses those values from the file as-is, so the status <strong>Date/time</strong> column will show the correct range (e.g. <code>2/20 7pm – 2/22 11pm</code> in local time).</p><h3 id="when-the-sheet-has-dates-properly-entered-sfcc-format" tabindex="-1">When the sheet has dates properly entered (SFCC format) <a class="header-anchor" href="#when-the-sheet-has-dates-properly-entered-sfcc-format" aria-label="Permalink to &quot;When the sheet has dates properly entered (SFCC format)&quot;">​</a></h3><p>If the sheet has <strong>REFRESH_DATE</strong> plus <strong>START_DATETIME</strong> / <strong>END_DATETIME</strong> (or full datetime cells), the pipeline keeps them in the format SFCC expects:</p><ol><li><strong>Parser</strong> — Reads the sheet and normalizes to <strong>ISO 8601</strong> (e.g. <code>2026-02-19T19:00:00.000Z</code>). Time-only values (e.g. <code>7:00 PM</code>) are combined with REFRESH_DATE; full datetimes (e.g. Excel date+time or ISO strings) are used as-is. Result is stored in <code>refresh.json</code> as <code>campaign.refresh.startTime</code> and <code>endTime</code>.</li><li><strong>Build / OCAPI</strong> — When building the campaign and slot configurations, those same ISO strings are passed through as <code>start_date</code> and <code>end_date</code> on the campaign and on each slot&#39;s <code>schedule</code>. No extra conversion is done.</li><li><strong>SFCC</strong> — OCAPI expects <code>schedule.start_date</code> and <code>schedule.end_date</code> in <strong>ISO 8601</strong>. The payload sends them in that form, so SFCC receives exactly what the sheet specified (in UTC).</li></ol><p>So: enter dates (and, if you want a specific go-live time, <strong>START_DATETIME</strong> / <strong>END_DATETIME</strong> or a full datetime). The system keeps everything as ISO 8601 from the sheet through to SFCC. Times in the sheet (e.g. <code>19:00</code> or <code>7:00 PM</code>) are interpreted as UTC when combined with the date unless you use a full datetime that already carries timezone (e.g. an ISO string with <code>Z</code> or offset).</p><p><strong>Current setup:</strong> If you use the conversion script (original → CONVERTED), when the original has no time the script now writes default <strong>START_DATETIME</strong> <code>19:00</code> and <strong>END_DATETIME</strong> <code>23:59</code> into the CONVERTED file so it is already in proper form. Use that CONVERTED file as your source (<code>activeSource: local</code>); the next pull/build will produce ISO 8601 through to SFCC. You can still override by putting times in the original (e.g. in the refresh label or in time columns) or by editing the CONVERTED file.</p><h2 id="site-locations-and-zones" tabindex="-1">Site locations and zones <a class="header-anchor" href="#site-locations-and-zones" aria-label="Permalink to &quot;Site locations and zones&quot;">​</a></h2><h3 id="loft" tabindex="-1">LOFT <a class="header-anchor" href="#loft" aria-label="Permalink to &quot;LOFT&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Site Location</th><th>Asset Type</th><th>Zones</th><th>Notes</th></tr></thead><tbody><tr><td>HOMEPAGE</td><td>HOMEPAGE</td><td>HP_MOBILE_CATS, HP_PROMO_NAV, HP_TOP_BANNER, HP_HERO, HP_2T, HP_CAT_IMAGE, HP_DUO, HP_TRIO, HP_FEATURED_SHOPS, HP_SLOTS, HP_BOTTOM_BANNER, HP_RFLK_WIDGET, HP_UGC_WIDGET, HP_CHARITABLE_HUB_BAR, HP_LEFT_NAV_CONTENT_SLOT</td><td>15 canonical zones, composed in <code>&lt;div class=&quot;g3-hp&quot;&gt;</code></td></tr><tr><td>HP CAT NAV</td><td>→ consolidated to HOMEPAGE</td><td>HP_MOBILE_CATS</td><td>Auto-merged during parsing</td></tr><tr><td>CAT IMAGE</td><td>→ consolidated to HOMEPAGE</td><td>HP_CAT_IMAGE</td><td>Auto-merged during parsing</td></tr><tr><td>SLOT 1–4</td><td>→ consolidated to HOMEPAGE</td><td>HP_SLOTS</td><td>Auto-merged during parsing</td></tr><tr><td>BOTTOM BANNER</td><td>→ consolidated to HOMEPAGE</td><td>HP_BOTTOM_BANNER</td><td>Auto-merged during parsing</td></tr><tr><td>FEATURED SHOPS</td><td>→ consolidated to HOMEPAGE</td><td>HP_FEATURED_SHOPS</td><td>Auto-merged during parsing</td></tr><tr><td>RFLK/UGC WIDGET</td><td>→ consolidated to HOMEPAGE</td><td>HP_RFLK/UGC_WIDGET</td><td>Auto-merged during parsing</td></tr><tr><td>PPH</td><td>PPH</td><td>PPH (single zone)</td><td></td></tr><tr><td>POPUP</td><td>POPUP</td><td>POPUP (single zone)</td><td></td></tr><tr><td>COUPONS</td><td>COUPONS</td><td>COUPONS (single zone)</td><td></td></tr><tr><td>PLP HEADER</td><td>PLP_HEADER</td><td>By category</td><td></td></tr><tr><td>FP</td><td>FP, FP DENIM, FP PANTS</td><td>By type (plp-callout)</td><td></td></tr><tr><td>NFP</td><td>NFP, NFP PP</td><td>By type (plp-callout)</td><td></td></tr></tbody></table><h3 id="ann-taylor" tabindex="-1">Ann Taylor <a class="header-anchor" href="#ann-taylor" aria-label="Permalink to &quot;Ann Taylor&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Site Location</th><th>Asset Type</th><th>Zones</th></tr></thead><tbody><tr><td>HP MAIN</td><td>HP MAIN</td><td>HP MAIN (single zone)</td></tr><tr><td>TOP BANNER</td><td>TOP BANNER (ABOVE MAIN)</td><td>Single zone</td></tr><tr><td>BOTTOM BANNER</td><td>BOTTOM BANNER (BELOW MAIN)</td><td>Single zone</td></tr><tr><td>PPH</td><td>PPH (SLOT 1-5)</td><td>PPH (SLOT 1), PPH (SLOT 2), etc.</td></tr><tr><td>POPUP</td><td>DISCLAIMER POP UP</td><td>Single zone</td></tr><tr><td>COUPONS</td><td>COUPON PAGE CAT151000X</td><td>By category ID</td></tr><tr><td>PLP</td><td>*PLP HEADER, *PLP BANNER</td><td>SALE PLP HEADER, etc.</td></tr></tbody></table><p>See <a href="/ocapi-docs.github.io/concepts/content-model.html">Slots, Assets, Zones</a> and <a href="/ocapi-docs.github.io/concepts/content-model.html">Asset Types (data flow)</a> for config details.</p><h2 id="ipid-format" tabindex="-1">IPID format <a class="header-anchor" href="#ipid-format" aria-label="Permalink to &quot;IPID format&quot;">​</a></h2><p>IPIDs (Internal Promotion IDs) are used for analytics tracking.</p><h3 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h3><p>The system builds every IPID from exactly these eight segments, in order:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{brand}_{page}_{device}_{zone}_{position}_{promo}_{destination}_{date}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="segment-reference-canonical" tabindex="-1">Segment reference (canonical) <a class="header-anchor" href="#segment-reference-canonical" aria-label="Permalink to &quot;Segment reference (canonical)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Segment</th><th>Placeholder</th><th>Description</th><th>Example values</th></tr></thead><tbody><tr><td>1. Brand</td><td><code>{brand}</code></td><td>Brand key (no cross-brand)</td><td><code>loft</code>, <code>at</code></td></tr><tr><td>2. Page</td><td><code>{page}</code></td><td>Page / asset type</td><td><code>hp</code>, <code>pph</code>, <code>popup</code>, <code>plp</code></td></tr><tr><td>3. Device</td><td><code>{device}</code></td><td>Device / audience</td><td><code>all</code>, <code>mobile</code>, <code>desktop</code></td></tr><tr><td>4. Zone</td><td><code>{zone}</code></td><td>Zone within the page</td><td><code>hero1ta1</code>, <code>main</code>, <code>hp-2t</code></td></tr><tr><td>5. Position</td><td><code>{position}</code></td><td>Item position in zone (1-based)</td><td><code>1</code>, <code>2</code>, <code>a</code></td></tr><tr><td>6. Promo</td><td><code>{promo}</code></td><td>Promo/copy slug or <code>np</code></td><td><code>sale50</code>, <code>30offsuiting</code>, <code>np</code></td></tr><tr><td>7. Destination</td><td><code>{destination}</code></td><td>Destination slug</td><td><code>saleviewall</code>, <code>suits</code>, <code>na</code></td></tr><tr><td>8. Date</td><td><code>{date}</code></td><td><strong>MMDDYY</strong> (6 digits only)</td><td><code>012626</code>, <code>012026</code></td></tr></tbody></table><ul><li><strong>Date segment:</strong> Exactly <strong>MMDDYY</strong> (6 digits). No other date format is used for IPIDs.</li><li><strong>Brand segment:</strong> <code>loft</code> or <code>at</code> only. <strong>No cross-brand use:</strong> LOFT assets must use only <code>loft_</code> IPIDs; Ann Taylor assets must use only <code>at_</code> IPIDs.</li></ul><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><table tabindex="0"><thead><tr><th>IPID</th><th>Breakdown</th></tr></thead><tbody><tr><td><code>loft_hp_all_hero1ta1_sale50_saleviewall_012626</code></td><td>LOFT, homepage, all audiences, hero zone, 50% sale, Jan 26 (MMDDYY: 012626)</td></tr><tr><td><code>at_pph_all_pph_1_30offsuiting_suits_012026</code></td><td>Ann Taylor, PPH, all, 30% off suiting, Jan 20 2026 (MMDDYY: 012026)</td></tr></tbody></table><h3 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h3><ul><li>Lowercase only</li><li>Underscores as separators</li><li><strong>Date at end: MMDDYY only (6 digits)</strong></li><li><strong>No cross-brand:</strong> Use the correct brand prefix for the current run</li><li>Be consistent across refreshes</li></ul><h2 id="destination-types" tabindex="-1">Destination types <a class="header-anchor" href="#destination-types" aria-label="Permalink to &quot;Destination types&quot;">​</a></h2><p>The system infers destination type from the value:</p><table tabindex="0"><thead><tr><th>Value Pattern</th><th>Inferred Type</th></tr></thead><tbody><tr><td><code>https://...</code></td><td>URL</td></tr><tr><td><code>CAT123456</code>, <code>CATA...</code></td><td>CATEGORY</td></tr><tr><td><code>/path/to/page</code></td><td>URL</td></tr><tr><td>Other</td><td>PRODUCT</td></tr></tbody></table><h2 id="multiple-refreshes-per-day" tabindex="-1">Multiple refreshes per day <a class="header-anchor" href="#multiple-refreshes-per-day" aria-label="Permalink to &quot;Multiple refreshes per day&quot;">​</a></h2><p>If you have multiple refreshes on the same day:</p><ol><li>Include time in the refresh name: &quot;1/26 3AM Site Changeout&quot;</li><li>The system assigns ordinals automatically: r1, r2, r3...</li><li>Use the TIME column for precise scheduling</li></ol><h2 id="multiple-sheets" tabindex="-1">Multiple sheets <a class="header-anchor" href="#multiple-sheets" aria-label="Permalink to &quot;Multiple sheets&quot;">​</a></h2><p>The system scans all sheets in the workbook and uses the first one that matches a known format.</p><p><strong>Priority order:</strong> CONVERTED &gt; BANNER &gt; FLAT_TIMED</p><p>To force a specific sheet, run: <code>make excel ARGS=&quot;--sheet=&#39;Sheet Name&#39;&quot;</code></p><h2 id="validation-checklist" tabindex="-1">Validation checklist <a class="header-anchor" href="#validation-checklist" aria-label="Permalink to &quot;Validation checklist&quot;">​</a></h2><p>Before saving your wireframe:</p><ul><li>[ ] All required columns present (REFRESH NAME, DATE, ACTION, ASSET TYPE, SITE LOCATION or SITE_LOCATION — both accepted)</li><li>[ ] Actions are valid (LAUNCH, UPDATE, REMOVE, NO_CHANGE)</li><li>[ ] Dates in a format Excel parses (e.g. M/D/YYYY)</li><li>[ ] No empty rows breaking parent-child grouping</li><li>[ ] IPIDs follow naming convention (see <a href="./validation-and-fixes.html">Validation and fixes</a>)</li></ul><h2 id="common-issues" tabindex="-1">Common issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common issues&quot;">​</a></h2><h3 id="rows-not-parsing" tabindex="-1">Rows not parsing <a class="header-anchor" href="#rows-not-parsing" aria-label="Permalink to &quot;Rows not parsing&quot;">​</a></h3><p><strong>Check:</strong></p><ul><li>Is there a parent row with REFRESH NAME and DATE?</li><li>Are required columns present?</li><li>Are there merged cells breaking the structure?</li></ul><h3 id="wrong-asset-type" tabindex="-1">Wrong asset type <a class="header-anchor" href="#wrong-asset-type" aria-label="Permalink to &quot;Wrong asset type&quot;">​</a></h3><p><strong>Check:</strong></p><ul><li>Is ASSET TYPE spelled correctly?</li><li>Is SITE LOCATION filled in?</li><li>Does the zone name match expected patterns?</li></ul><h3 id="dates-not-recognized" tabindex="-1">Dates not recognized <a class="header-anchor" href="#dates-not-recognized" aria-label="Permalink to &quot;Dates not recognized&quot;">​</a></h3><p><strong>Check:</strong></p><ul><li>Use M/D/YYYY format (1/26/2026)</li><li>Avoid text formatting on date cells</li><li>Check Excel is interpreting as date, not text</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a> — How to run commands</li><li><a href="/ocapi-docs.github.io/guides/templates.html">Template Authoring</a> — How to edit HTML templates</li><li><a href="./validation-and-fixes.html">Validation and fixes</a> — Errors and how to fix in Excel</li><li><a href="/ocapi-docs.github.io/reference/commands.html">Commands Reference</a> — All make commands</li></ul>`,82)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
